      "sambandha": "සර්වනාම කීම පිණිස ‘සබ්බ + යො’ යන මෙහි ‘යො’ අනුවර්තනය වන කල්හි සර්වනාම අකාරයා කෙරෙන් පර ප්‍රථමා යො හට එකාරය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "සබ්බනාමකාරතො, එ, පඨමොති තීණි පදානි.",
      "pada": "සබ්බනාමකාරතො, එ, පඨමො යනුවෙන් පද තුනකි.",
