    "anuvattana": "සබ්බනාමතො - 200 (ක.164) සබ්බනාමකාරතෙ පඨමො",
    "vutti": "‘සබ්බනාමතො’ති ච වත්තතෙ.<br><br>සබ්බතො සබ්බනාමතො පරස්ස නංවචනස්ස සං සානංඉච්චෙතෙ ආදෙසා හොන්ති.<br>සබ්බෙසං සබ්බෙසානං,<br>සබ්බස්මා සබ්බම්හා, සබ්බෙහි සබ්බෙභි,<br>සබ්බස්ස, සබ්බෙසං සබ්බෙසානං,<br>සබ්බස්මිං සබ්බම්හි, සබ්බෙසු.<br>ඉත්ථියං ‘ඉත්ථියමතො ආප්පච්චයො’ති ආප්පච්චයො. අඤ්ඤං කඤ්ඤාසද්දසමං අඤ්ඤත්‍ර ස නං ස්මිංවචනෙහි.<br>සබ්බා පජා, සබ්බා සබ්බායො,<br>හෙ සබ්බෙ, හෙ සබ්බා සබ්බායො,<br>සබ්බං, සබ්බා සබ්බායො,<br>සබ්බාය, සබ්බාහි සබ්බාභි.",
    "vutti_sanna": "**සබ්බනාමතොති ච වත්තතෙ**, ‘සබ්බනාමකාරතෙ පඨමො’ සූත්‍රයෙන් සබ්බනාමතො යනු වැටේ.<br><br>**සබ්බතො සබ්බනාමතො**, ස්ත්‍රී පුං නපුංසක ලිඞ්ගයෙන් විශිෂ්ට වූ සියලු සර්වනාම සංඥා ඇති ශබ්දයන් කෙරෙන්; **පරස්ස නංවචනස්ස**, පර වූ නං වචනය හට; **සං සානං ඉච්චෙතෙ ආදෙසා**, සං, සානං යන ආදේශයෝ දෙදෙන; **හොන්ති**, වෙත්; **සබ්බෙසං සබ්බෙසානං**, සියල්ලන්ට.<br><br>**ඉත්ථියං**, ස්ත්‍රීලිඞ්ගයෙහි; **ඉත්ථියමතො ආප්පච්චයොති ආප්පච්චයො**, ‘ඉත්ථියමතො ආප්පච්චයො’ සූත්‍රයෙන් ආ ප්‍රත්‍යය වේ; **අඤ්ඤං**, අන්‍ය වූ රූප; **කඤ්ඤාසද්දසමං**, කඤ්ඤා ශබ්දය හා සමයි; **අඤ්ඤත්‍ර ස නං ස්මිංවචනෙහි**, ස, නං, ස්මිං යන වචනයන් හැර; **සබ්බා පජා**, සියලු සත්වයෝ.",
    "shadakara": {
      "sambandha_pali": "‘සබ්බනාමතො’ති ච වත්තමානෙ සබ්බනාමතො පරස්ස නංවචනස්ස සංසානංආදෙසවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘සබ්බනාමතො’ අනුවර්තනය වන කල්හි සර්වනාමයන් කෙරෙන් පර නං වචනයට සං, සානං ආදේශ විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "සබ්බතො, නං, සංසානංති තීණි පදානි.",
      "pada": "සබ්බතො, නං, සංසානං යනුවෙන් පද තුනකි.",
      "padattha_pali": "සබ්බතො සබ්බනාමතො පරස්ස නංවචනස්ස සං සානං ඉච්චෙතෙ ආදෙසා හොන්තිති අත්ථො.",
      "padattha": "සියලු සර්වනාමයන් කෙරෙන් පර නං වචනයට සං, සානං ආදේශයෝ වෙත් යනු අර්ථයි.",
      "padaviggaha_pali": "සඤ්ච සානඤ්ච සංසානං.",
      "padaviggaha": "සං ද සානං ද සංසානං නම්.",
      "chodana_pali": "‘සබ්බනාමතො’ති අනුවත්තමානෙ ‘සබ්බතො’ති කිමත්ථං?",
      "chodana": "‘සබ්බනාමතො’ අනුවර්තනය වන කල්හි ‘සබ්බතො’ යනු කුමක් පිණිසද?",
      "parihara_pali": "අකාරාදිනියමං කත්වා අනුවත්තනතො සබ්බලිඞ්ගිකසබ්බනාමගහණත්ථං — ඉත්ථිලිඞ්ගෙපි සබ්බාසං සබ්බාසානං.",
      "parihara": "අකාරාදි නියමය කොට අනුවර්තනය වන හෙයින් සියලු ලිඞ්ග ඇති සර්වනාම ගැනීම පිණිසයි — ස්ත්‍රීලිඞ්ගයෙහි ද සබ්බාසං, සබ්බාසානං."
    },
