    "sub_khanda_name": "සබ්බනාමං",
    "sutta_name": "205. ඝො රස්සං",
    "sutta_meaning": "**එකවචනෙසු**, එකවචනයන්හි වූ; **සංසාසු**, සංසායනාදේශයන් පරකල්හි; **ඝො**, ඝසංඥයතෙම; **රස්සං**, හ්‍රස්වයට පැමිණේ.",
    "sutta_type": "රස්සවිධාන සූත්‍ර (කච්. 66)",
    "pada_cheda": "ඝො + රස්සං (ද්විපද සූත්‍රයකි)",
    "anuvattana": "සංසාස්වෙකවචනෙසු ච - 206 (ක.62) සංසාස්වෙකවචනෙසු ච",
    "vutti": "‘සංසාස්වෙකවචනෙසු චා’ති වත්තතෙ.<br><br>ඝසඤ්ඤො ආකාරො රස්සමාපජ්ජතෙ සංසාස්වෙකවචනෙසු විභත්තාදෙසෙසු පරෙසු.<br>...... ආ→අ + සං / සා",
    "vutti_sanna": "**සංසාස්වෙකවචනෙසු චාති වත්තතෙ**, ‘සංසාස්වෙකවචනෙසු ච’ සූත්‍රයෙන් සංසාස්වෙකවචනෙසු යනු වැටේ.<br><br>**ඝසඤ්ඤො ආකාරො**, ඝ සංඥක වූ ආකාරය තෙම; **සංසාස්වෙකවචනෙසු**, එකවචනස්ථානයෙහි සම්භූත වූ සං, සා යන; **විභත්තාදෙසෙසු පරෙසු**, විභක්තීන්ට ආදේශ වූ මොවුන් පර කල්හි; **රස්සමාපජ්ජතෙ**, හ්‍රස්ව බවට පැමිණේ.",
    "shadakara": {
      "sambandha_pali": "‘සංසාස්වෙකවචනෙසු චා’ති වත්තමානෙ ඝසඤ්ඤස්ස රස්සවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘සංසාස්වෙකවචනෙසු ච’ අනුවර්තනය වන කල්හි ඝ සංඥකයාට හ්‍රස්වය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "ඝො, රස්සංති ද්වෙ පදානි.",
      "pada": "ඝො, රස්සං යනුවෙන් පද දෙකකි.",
      "padattha_pali": "ඝසඤ්ඤො ආකාරො රස්සමාපජ්ජතෙ සංසාස්වෙකවචනෙසු විභත්තාදෙසෙසු පරෙසුති අත්ථො.",
      "padattha": "එකවචනයට ආදේශ වූ සං, සා පර කල්හි ඝ සංඥක ආකාරය හ්‍රස්වයට පැමිණේ යනු අර්ථයි.",
      "padaviggaha_pali": "රස්සස්ස භාවො රස්සං.",
      "padaviggaha": "හ්‍රස්වයාගේ භාවය රස්ස නම්.",
      "chodana_pali": "‘අඝො රස්ස’න්තිආදිනා ඝස්ස රස්සත්තං නත්ථි, කථං සබ්බස්සා?",
      "chodana": "‘අඝො රස්සං’ ආදියෙන් ඝ හට හ්‍රස්වය නැත; සබ්බස්සා වන්නේ කෙසේද?",
      "parihara_pali": "ඉමිනා විසුං විධානතො සංසාසු ඝස්සාපි රස්සත්තං — සබ්බස්සා, සබ්බස්සං.",
      "parihara": "මෙයින් වෙනම විධානය කළ හෙයින් සං, සා පර කල්හි ඝ හට ද හ්‍රස්ව වේ — සබ්බස්සා, සබ්බස්සං."
    },
