    "sutta_name": "206. සංසාස්වෙකවචනෙසු ච",
    "sutta_meaning": "**එකවචනෙසු**, එක වචනයන්ට ආදේශවූ; **සංසාසු ච**, සංසායනාදෙශයන් පරකල්හිද, සාගමො; සකාරාගමය වේ",
    "sutta_type": "ආගමවිධාන සූත්‍ර (කච්. 62)",
    "pada_cheda": "සංසාසු + එකවචනෙසු + ච (තිපද සූත්‍රයකි)",
    "anuvattana": "සාගමො - 86 (ක.61) සාගමො සෙ",
    "vutti": "‘සාගමො’ති වත්තතෙ.<br><br>සං සාඉච්චෙතෙසු එකවචනට්ඨානසම්භූතෙසු විභත්තාදෙසෙසු පරෙසු ලිඞ්ගම්හා සකාරාගමො හොති.<br>සබ්බස්සා සබ්බාය, සබ්බාසං සබ්බාසානං,<br>සබ්බාය, සබ්බාහි සබ්බාභි,<br>සබ්බස්සා සබ්බාය, සබ්බාසං සබ්බාසානං.",
    "vutti_sanna": "**සාගමොති වත්තතෙ**, ‘සාගමො සෙ’ සූත්‍රයෙන් සාගමො යනු වැටේ.<br><br>**සං සා ඉච්චෙතෙසු**, සං, සා යන මොවුන්; **එකවචනට්ඨානසම්භූතෙසු**, එකවචන ස්ථානයෙහි සම්භව වූ; **විභත්තාදෙසෙසු පරෙසු**, විභක්ත්‍යාදේශයන් පර කල්හි; **ලිඞ්ගම්හා**, (සර්වනාම) ලිඞ්ගයා කෙරෙන් පරව; **සකාරාගමො හොති**, සකාරාගමයක් වේ; **සබ්බස්සා සබ්බාය**, සියල්ලියට; **සබ්බාසං සබ්බාසානං**, සියල්ලියන්ට.",
    "shadakara": {
      "sambandha_pali": "‘සාගමො’ති වත්තමානෙ සංසාසු එකවචනාදෙසෙසු සකාරාගමවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘සාගමො’ අනුවර්තනය වන කල්හි එකවචනයට ආදේශ වූ සං, සා පර කල්හි සකාරාගමය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "සංසාසු, එකවචනෙසු, චති තීණි පදානි.",
      "pada": "සංසාසු, එකවචනෙසු, ච යනුවෙන් පද තුනකි.",
      "padattha_pali": "සං සා ඉච්චෙතෙසු එකවචනට්ඨානසම්භූතෙසු විභත්තාදෙසෙසු පරෙසු ලිඞ්ගම්හා සකාරාගමො හොතිති අත්ථො.",
      "padattha": "එකවචන ස්ථානයෙහි වූ සං, සා ආදේශ පර කල්හි ලිඞ්ගයා කෙරෙන් සකාරාගමය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "එකවචනානං ඨානෙ සම්භූතා එකවචනා.",
      "padaviggaha": "එකවචනයන්ගේ ස්ථානයෙහි ඉපදුණු ආදේශයෝ එකවචන නම් වෙත්.",
      "chodana_pali": "‘සාගමො සෙ’ති සෙ ආගමෙ සිද්ධෙ කිමත්ථමිදං?",
      "chodana": "‘සාගමො සෙ’ සූත්‍රයෙන් ස පර කල්හි ආගමය සිද්ධ කල්හි මෙය කුමට ද?",
      "parihara_pali": "තත්ථ සෙ ඉති සවිභත්තියෙව ගහිතා, න සංසාදෙසා; තස්මා ඉමිනා එකවචනෙසු සංසාසු සකාරාගමො — සබ්බස්සා; එකවචනෙසූති කිං? සබ්බාසං.",
      "parihara": "එහි ‘සෙ’ යනු ස විභක්තියම ගැනේ, සං සා ආදේශ නොගැනේ; එහෙයින් මෙයින් එකවචන සං, සා පර කල්හි සකාරාගමය වේ — සබ්බස්සා. ‘එකවචනෙසු’ යනු නං හට වන සං (බහුවචන) හි නොවීම පිණිසයි — සබ්බාසං."
    },
