    "sutta_name": "211. එතතෙසං තො",
    "sutta_meaning": "**අනපුංසකානං**, නපුංසකලිංඟු නොවූ; **එතතෙසං**, එතශබ්ද තශබ්ද දෙදෙනාගේ; **තො**, තකාරය තෙම; **සිම්හි**, සිවිභක්ති පරකල්හි; **සං**, සකාරයට පැමිණේ.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 174)",
    "pada_cheda": "එතතෙසං + තො (ද්විපද සූත්‍රයකි)",
    "anuvattana": "අනුවර්තනයක් නැත",
    "vutti": "එත තඉච්චෙතෙසං අනපුංසකානං තකාරො සකාරමාපජ්ජතෙ සිම්හි විභත්තිම්හි. සො පුරිසො.<br>සබ්බනාමග්ගහණඤ්ච, ඉතො තග්ගහණඤ්ච වත්තතෙ.<br>සබ්බනාමස්ස -200 - ක.(164) - සබ්බනාමකාරතෙ පඨමො.<br>තස්ස -211 - ක.(174) - එතතෙසං තො.",
    "vutti_sanna": "**ත එත ඉම අමු කිං ඉච්චෙතෙ**, ත, එත, ඉම, අමු, කිං යන මේ සර්වනාම ශබ්දයෝ; **පරම්මුඛ සමීප අච්චන්තසමීප දූර පුච්ඡනත්ථවචනා**, (යථාක්‍රමයෙන්) පරම්මුඛ (ඒ), සමීප (අර/මෙ), අත්‍යන්ත සමීප (මේ), දූර (අසුවල්), ප්‍රශ්න (කවර) යන අර්ථ කියන්නෝ ය. **තසද්දස්ස භෙදො**, ත ශබ්දයාගේ රූපභේදය (කියනු ලැබේ); **ත සි ඉති ඉධ**, ත සි යන මෙහි; **අනපුංසකස්සායං සිම්හීති සන්ති ච වත්තතෙ**, ‘අනපුංසකස්සායං සිම්හි’ සූත්‍රයෙන් අනපුංසකස්ස, සිම්හි යනු ද, ‘අමුස්ස මො සං’ සූත්‍රයෙන් සං යනු ද වැටේ.<br><br>**එත ත ඉච්චෙතෙසං**, එත, ත යන මේ සර්වනාම දෙදෙනාගේ; **අනපුංසකානං**, නපුංසකලිඞ්ග නොවූ (ස්ත්‍රී පුං ලිඞ්ගයන්හි වැටෙන); **තකාරො**, තකාරය තෙම; **සකාරමාපජ්ජතෙ**, සකාර බවට පැමිණේ; **සිම්හි විභත්තිම්හි**, සි විභක්තිය පර කල්හි; **සො (පුරිසො)**, ඒ පුරුෂයා.",
    "shadakara": {
      "sambandha_pali": "තසද්දස්ස භෙදෙ ‘ත සි’ඉතීධ ‘අනපුංසකස්ස, සිම්හි, සං’ඉති ච වත්තමානෙ එතතෙසං තකාරස්ස සකාරවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "ත ශබ්දයේ රූපභේදයෙහි ‘ත + සි’ යන මෙහි ‘අනපුංසකස්ස, සිම්හි, සං’ අනුවර්තනය වන කල්හි එත, ත ශබ්දයන්ගේ තකාරයට සකාරය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "එතතෙසං, තොති ද්වෙ පදානි.",
      "pada": "එතතෙසං, තො යනුවෙන් පද දෙකකි.",
      "padattha_pali": "එත තඉච්චෙතෙසං අනපුංසකානං තකාරො සකාරමාපජ්ජතෙ සිම්හි විභත්තිම්හිති අත්ථො.",
      "padattha": "සි විභක්තිය පර කල්හි නපුංසක නොවූ එත, ත ශබ්දයන්ගේ තකාරය සකාරයට පැමිණේ යනු අර්ථයි.",
      "padaviggaha_pali": "එතො ච තො ච එතතා, තෙසං එතතෙසං. තො ඉති තකාරො.",
      "padaviggaha": "එත ද ත ද එතත නම්; ඔවුන්ගේ එතතෙසං. ‘තො’ යනු තකාරයයි.",
      "chodana_pali": "‘අනපුංසකස්සා’ති එකවචනනිද්දෙසෙ ‘අනපුංසකාන’න්ති කස්මා වුත්තං?",
      "chodana": "‘අනපුංසකස්ස’ යනු එකවචනයෙන් අනුවර්තනය වූව ද වෘත්තියෙහි ‘අනපුංසකානං’ යයි බහුවචනයෙන් කීයේ කුමක් හෙයින් ද?",
      "parihara_pali": "‘එතතෙස’න්ති අපෙක්ඛිත්වා වචනවිපල්ලාසෙන; නපුංසකෙ පන තං, එතං.",
      "parihara": "‘එතතෙසං’ යන්න අපේක්ෂා කොට වචන විපර්යාසයෙන් කීහ; නපුංසකයෙහි වනාහි සකාරය නොවේ — තං, එතං."
    },
    "extended_commentary": "<p>ත ශබ්දය පරම්මුඛ (ඇසට නොපෙනෙන) දෙය ද, එත ශබ්දය සමීප දෙය ද, ඉම ශබ්දය අත්‍යන්ත සමීප දෙය ද, අමු ශබ්දය දූර දෙය ද, කිං ශබ්දය ප්‍රශ්නාර්ථය ද කියයි (සන්නය).</p>",
