      "pada": "තස්ස, වා, නත්තං, සබ්බත්ථ යනුවෙන් පද සතරකි.",
      "padattha_pali": "තඉච්චෙතස්ස සබ්බනාමස්ස තකාරස්ස නත්තං හොති වා සබ්බත්ථ ලිඞ්ගෙසුති අත්ථො.",
      "padattha": "සියලු ලිඞ්ගයන්හි ත සර්වනාමයාගේ තකාරයට විකල්පයෙන් නකාරය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "නස්ස භාවො නත්තං. සබ්බස්මිං සබ්බත්ථ.",
      "padaviggaha": "නකාරයාගේ භාවය නත්තං නම්; සියල්ලෙහි සබ්බත්ථ නම්.",
