      "parihara_pali": "සබ්බලිඞ්ගෙසු සබ්බවිභත්තීසු ච නත්තවිධානත්ථං; අනන්තරසුත්තෙ තග්ගහණෙ සතිපි සබ්බනාමගහණං තසද්දස්සෙව ගහණත්ථං.",
      "parihara": "සියලු ලිඞ්ගයන්හි හා විභක්තීන්හි නකාරය විධානය පිණිසයි; අනන්තර සූත්‍රයෙහි ත ග්‍රහණය ඇති කල්හි ද සර්වනාම ග්‍රහණය ත ශබ්දයම ගැනීම පිණිසයි."
