    "pada_cheda": "තස්සා + වා (ද්විපද සූත්‍රයකි)",
    "anuvattana": "අනුවර්තනයක් නැත",
    "vutti": "තාඉච්චෙතස්ස ඉත්ථියං වත්තමානස්ස අන්තස්ස ඉකාරො හොති වා සං සාස්වෙකවචනෙසු විභත්තාදෙසෙසු.<br>තා + සං / සා / ස්සාය<br>ත්-ආ→ඉ + සං / සා / ස්සාය<br>ති + සං / සා / ස්සාය<br>තිස්සාය තස්සාය අස්සාය නස්සාය අස්සා නස්සා තිස්සා තස්සා නාය තාය, නාසං තාසං.<br>පඤ්චමීඡට්ඨීසු තතියාචතුත්ථීසමං.<br>සත්තමියං අස්සං නස්සං තිස්සං තස්සං නායං තායං, නාසු තාසු.<br>නපුංසකෙ සිම්හි සාදෙසාභාවා නත්තං.<br>නං තං, නානි තානි,<br>නං තං, නානි තානි,<br>නෙන තෙන ඉච්චාදි පුල්ලිඞ්ගසමං.<br>එත සි, ‘එතතෙසං තො’ති සකාරාදෙසො.<br>එසො පුරිසො, එතෙ,<br>එතං, එතෙ ඉච්චාදි සබ්බසද්දසමං.<br>ඉත්ථියං එතා සි, සාදෙසො.<br>එසා කඤ්ඤා, එතා එතායො,<br>එතං, එතා එතායො,<br>එතාය, එතාහි එතාභි.<br>ස ස්මිංසු පන ‘සංසාස්වෙකවචනෙසු චා’ති වත්තතෙ.<br>සංසාසු, එකවචනෙසු ච − 206 - (ක.62) - සංසාස්වෙකවචනෙසු ච.",
    "vutti_sanna": "**සංසාස්වෙකවචනෙසු ච ඉ ඉති ච වත්තතෙ**, ‘සංසාස්වෙකවචනෙසු ච’ සූත්‍රයෙන් සංසාස්වෙකවචනෙසු යනු ද, ‘එතිමාසමි’ සූත්‍රයෙන් ඉ යනු ද වැටේ.<br><br>**තා ඉච්චෙතස්ස**, තා යන මේ සර්වනාමයාගේ; **ඉත්ථියං වත්තමානස්ස**, ස්ත්‍රීලිඞ්ගයෙහි වැටෙන්නා වූ; **අන්තස්ස**, අන්ත ස්වරය හට; **ඉකාරො හොති වා**, විකල්පයෙන් ඉකාරයක් වේ; **සංසාස්වෙකවචනෙසු විභත්තාදෙසෙසු**, එකවචනස්ථානයෙහි සම්භූත වූ සං, සා යන විභක්ත්‍යාදේශයන් පර කල්හි (සාදෙස ගතික හෙයින් ස්සාය ආදේශය පර කල්හි ද); **තිස්සාය තස්සාය අස්සාය නස්සාය අස්සා නස්සා තිස්සා තස්සා නාය තාය, නාසං තාසං**; **පඤ්චමීඡට්ඨීසු තතියාචතුත්ථීසමං**, පඤ්චමී ඡට්ඨී විභක්තීන්හි රූප තතියා චතුත්ථී රූප හා සම ය; **සත්තමියං**, සත්තමී විෂයයෙහි; **අස්සං නස්සං තිස්සං තස්සං නායං තායං, නාසු තාසු**.",
    "shadakara": {
      "sambandha_pali": "‘සංසාස්වෙකවචනෙසු ච, ඉ’ඉති ච වත්තමානෙ තාසද්දස්ස අන්තස්ස ඉකාරවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘සංසාස්වෙකවචනෙසු ච, ඉ’ අනුවර්තනය වන කල්හි තා ශබ්දයේ අන්තයට ඉකාරය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "තස්සා, වාති ද්වෙ පදානි.",
      "pada": "තස්සා, වා යනුවෙන් පද දෙකකි.",
      "padattha_pali": "තාඉච්චෙතස්ස ඉත්ථියං වත්තමානස්ස අන්තස්ස ඉකාරො හොති වා සංසාස්වෙකවචනෙසු විභත්තාදෙසෙසුති අත්ථො.",
      "padattha": "එකවචනයට ආදේශ වූ සං, සා පර කල්හි ස්ත්‍රීලිඞ්ග තා ශබ්දයේ අන්තයට විකල්පයෙන් ඉකාරය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "තස්සාති අන්තාපෙක්ඛායං ඡට්ඨී (ආප්පච්චයන්තනිද්දෙසො).",
      "padaviggaha": "‘තස්සා’ යනු අන්තය අපේක්ෂා කරන ෂෂ්ඨියකි (ආ ප්‍රත්‍යයාන්ත නිර්දේශයයි).",
      "chodana_pali": "ස්සායාදෙසෙ කථං ඉකාරො?",
      "chodana": "ස්සාය ආදේශය පර කල්හි ඉකාරය වන්නේ කෙසේද?",
      "parihara_pali": "සාදෙසගතිකත්තා ස්සායාදෙසෙපි ඉකාරො — තිස්සාය.",
      "parihara": "ස්සාය ආදේශය සා ආදේශය ගති ඇති හෙයින් එය පර කල්හි ද ඉකාරය වේ — තිස්සාය."
    },
