    "sutta_meaning": "**අනපුංසකස්ස**, නපුංසකලිඟු නොවූ; **සබ්බස්ස ඉමස්ස**, සියලුම ඉම ශබ්දයට; **සිම්හි**, සිවිභක්ති පරකල්හි; **අයං**, අයං යනාදේශ වේ.",
