    "vutti_sanna": "**නපුංසකෙ**, නපුංසකලිඞ්ගයෙහි; **එතං එතානි, එතං එතානි, සෙසං ඤෙය්‍යං**, සෙසු රූප පුල්ලිඞ්ගයෙහි කී නයින් දත යුතු. **ඉමසද්දස්ස භෙදො**, ඉම ශබ්දයාගේ රූපභේදය ඇත; **ඉම සි**, ඉම ශබ්දයා කෙරෙන් සි විභක්තිය වේ; **සබ්බස්සිමස්සාති වත්තතෙ**, ‘සබ්බස්සිමස්සෙ වා’ සූත්‍රයෙන් සබ්බස්ස ඉමස්ස යනු වැටේ.<br><br>**ඉමසද්දස්ස සබ්බස්සෙව**, සියලු ඉම ශබ්දය හට; **අනපුංසකස්ස**, නපුංසක නොවූ; **අයං ආදෙසො හොති**, අයං යන ආදේශය වේ; **සිම්හි විභත්තිම්හි**, සි විභක්තිය පර කල්හි; **සිලොපො**, සි විභක්තිය ලොප් වේ; **අයං (පුරිසො)**, මේ පුරුෂයා; **ඉමෙ, ඉමං ඉමෙ**.",
