    "sutta_name": "219. අනිමි නාම්හි ච",
    "sutta_meaning": "**සබ්බස්ස**, සියලුම; **ඉමස්ස**, ඉම ශබ්දයට; **නාම්හි ච**, නාවිභක්ති පර කල්හිද; **අනඉමි**, අන ඉමි යන ආදේශ දෙක වෙත්.",
