    "sutta_name": "229. නො ච ද්වාදිතො නංම්හි",
    "sutta_meaning": "**නම්හි**, නංවිභක්තී පරකල්හි; **ද්වාදිතො**, ද්විශබ්දාදීන් කෙරෙන්; **නො ච ආගමො**, නකාරයෙක්ද ආගම වේ.",
    "sutta_type": "ආගමවිධාන සූත්‍ර (කච්. 67)",
    "pada_cheda": "නො + ච + ද්වාදිතො + නංම්හි (චතුප්පද සූත්‍රයකි)",
    "anuvattana": "ආගමො - 86 (ක.61) සාගමො සෙ; සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ",
    "vutti": "නංම්හි දීඝෙ සම්පත්තෙ –<br><br>ද්විඉච්චෙවමාදිතො සඞ්ඛ්‍යාතො නකාරාගමො හොති නංම්හි විභත්තිම්හි. චසද්දග්ගහණෙන ඉත්ථියං ති චතුසද්දතො ස්සඤ්චාගමො නංම්හි විභත්තිම්හි.<br>ද්වින්නං දුවින්නං වා,<br>ද්වීහි ද්වීභි,<br>ද්වින්නං දුවින්නං,<br>ද්වීසු.<br>තිසද්දස්ස භෙදො. ‘ති යො’ඉතීධ<br>යොලොපෙ සම්පත්තෙ<br>‘යොසූ’ති වත්තතෙ.<br>ඉත්ථිපුමනපුංසකසංඛ්‍යානං - --- (ක.131) ඉත්ථිපුමනපුංසකසඞ්ඛ්‍යං.",
    "vutti_sanna": "**නංම්හි දීඝෙ සම්පත්තෙ**, නං පර කල්හි ‘සුනංහිසු ච’ සූත්‍රයෙන් පූර්වස්වරයට දීර්ඝය සම්ප්‍රාප්ත කල්හි (අපවාද සූත්‍රයක් කියනු ලැබේ); **ආගමො**, ‘සාගමො සෙ’ සූත්‍රයෙන් (මණ්ඩූකගතියෙන්) ආගම ග්‍රහණය වැටේ.<br><br>**ද්වි ඉච්චෙවමාදිතො සඞ්ඛ්‍යාතො**, ද්වි ආදී සංඛ්‍යාවාචී ශබ්දයන් කෙරෙන් පරව; **නකාරාගමො හොති**, නකාරාගමය වේ; **නංම්හි විභත්තිම්හි**, නං විභක්තිය පර කල්හි; **චසද්දග්ගහණෙන**, ච ශබ්දයාගේ ගැනීමෙන්; **ඉත්ථියං තිචතුසද්දතො**, ස්ත්‍රීලිඞ්ගයෙහි ති, චතු ශබ්දයන් කෙරෙන්; **ස්සඤ්චාගමො හොති**, ස්සං යන ආගමය ද වේ; **නංම්හි විභත්තිම්හි**, නං පර කල්හි; **ද්වින්නං දුවින්නං වා**; **ද්වීහි ද්වීභි**; **ද්වීසු**.",
    "shadakara": {
      "sambandha_pali": "නංම්හි දීඝෙ සම්පත්තෙ ‘ආගමො’ති වත්තමානෙ ද්වාදිතො නකාරාගමවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "නං පර කල්හි දීර්ඝය සම්ප්‍රාප්ත කල්හි ‘ආගමො’ අනුවර්තනය වන කල්හි ද්වි ආදියෙන් නකාරාගමය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "නො, ච, ද්වාදිතො, නංම්හිති චත්තාරි පදානි.",
      "pada": "නො, ච, ද්වාදිතො, නංම්හි යනුවෙන් පද සතරකි.",
      "padattha_pali": "ද්විඉච්චෙවමාදිතො සඞ්ඛ්‍යාතො නකාරාගමො හොති නංම්හි විභත්තිම්හිති අත්ථො.",
      "padattha": "නං විභක්තිය පර කල්හි ද්වි ආදී සංඛ්‍යාවන් කෙරෙන් නකාරාගමය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "ද්වි ආදි යස්ස සඞ්ඛ්‍යාගණස්ස සො ද්වාදි, තතො ද්වාදිතො.",
      "padaviggaha": "ද්වි ආදි කොට ඇති සංඛ්‍යා සමූහය ද්වාදි නම්; ඔහු කෙරෙන් ද්වාදිතො.",
      "chodana_pali": "චසද්දො කිමත්ථො?",
      "chodana": "ච ශබ්දය කුමක් පිණිසද?",
      "parihara_pali": "ඉත්ථියං තිචතුසද්දතො ස්සඤ්චාගමත්ථො — තිස්සන්නං, චතස්සන්නං.",
      "parihara": "ස්ත්‍රීලිඞ්ගයෙහි ති, චතු ශබ්දයන්ගෙන් ස්සං ආගමය පිණිසයි — තිස්සන්නං, චතස්සන්නං."
    },
